package ai

func init() {
	for k, v := range map[string][2]string{
		"title-internal-verified": {"%s is reachable from this network and refuses anonymous clients", "%s est joignable depuis ce réseau et refuse les clients anonymes"},
		"progress":                {"checking %d (%s)…", "je vérifie %d (%s)…"},

		"chk-ssh-none":     {"accepts logins with no authentication at all", "accepte les connexions sans aucune authentification"},
		"fix-ssh-none":     {"Require public-key authentication on this server immediately.", "Exigez tout de suite une authentification par clé sur ce serveur."},
		"chk-ssh-password": {"accepts password logins (%s): bots can try to guess them", "accepte la connexion par mot de passe (%s) : des robots peuvent essayer de les deviner"},
		"fix-ssh-password-openssh": {"In /etc/ssh/sshd_config set PasswordAuthentication no and KbdInteractiveAuthentication no, then systemctl reload ssh (keep a session open while you test).",
			"Dans /etc/ssh/sshd_config, mettez PasswordAuthentication no et KbdInteractiveAuthentication no, puis systemctl reload ssh (gardez une session ouverte pendant le test)."},
		"fix-ssh-password-other": {"Turn off password and keyboard-interactive logins in this SSH server's settings and keep keys only.",
			"Désactivez la connexion par mot de passe et keyboard-interactive dans la configuration de ce serveur SSH, et gardez seulement les clés."},
		"fix-ssh-password-wings": {"Wings checks SFTP passwords against the panel, so players need them: keep them, but require strong passwords and two-factor authentication on the panel, or move players to SSH keys (Pterodactyl 1.11 and later).",
			"Wings vérifie les mots de passe SFTP auprès du panneau, les joueurs en ont donc besoin : gardez-les, mais exigez des mots de passe solides et la double authentification sur le panneau, ou faites passer les joueurs aux clés SSH (Pterodactyl 1.11 et plus)."},
		"chk-ssh-keys": {"only accepts key-based logins: nothing to guess", "n'accepte que les clés : rien à deviner"},
		"chk-ssh-weak": {"still offers weak algorithms: %s", "propose encore des algorithmes faibles : %s"},
		"fix-ssh-weak-openssh": {"Add to /etc/ssh/sshd_config: %s, then systemctl reload ssh.",
			"Ajoutez dans /etc/ssh/sshd_config : %s, puis systemctl reload ssh."},
		"fix-ssh-weak-go": {"Remove them from the server's algorithm lists (with Go's x/crypto/ssh: ServerConfig.KeyExchanges and ServerConfig.MACs).",
			"Retirez-les des listes d'algorithmes du serveur (avec x/crypto/ssh en Go : ServerConfig.KeyExchanges et ServerConfig.MACs)."},

		"chk-kubelet-401": {"refuses anonymous requests", "refuse les requêtes anonymes"},
		"chk-kubelet-403": {"accepts anonymous requests but denies them (anonymous-auth is on; turning it off is safer)",
			"accepte les requêtes anonymes mais les refuse (anonymous-auth est activé ; le désactiver est plus sûr)"},
		"chk-kubelet-200": {"answers anonymous requests: anyone reaching it can list pods and run commands in them",
			"répond aux requêtes anonymes : quiconque l'atteint peut lister les pods et y exécuter des commandes"},
		"fix-kubelet": {"Set --anonymous-auth=false and --authorization-mode=Webhook on the kubelet, and close 10250 to everything but the control plane.",
			"Réglez --anonymous-auth=false et --authorization-mode=Webhook sur le kubelet, et fermez le 10250 à tout sauf au plan de contrôle."},
		"chk-api-401":       {"refuses anonymous requests", "refuse les requêtes anonymes"},
		"chk-api-403":       {"accepts anonymous requests but denies them", "accepte les requêtes anonymes mais les refuse"},
		"chk-api-200":       {"answers anonymous API discovery", "répond aux requêtes anonymes de découverte de l'API"},
		"fix-api-anonymous": {"Start the API server with --anonymous-auth=false, or remove the RBAC bindings that grant system:anonymous.", "Lancez le serveur d'API avec --anonymous-auth=false, ou retirez les droits RBAC accordés à system:anonymous."},
		"chk-docker-open":   {"answers without authentication: whoever reaches it is root on the host", "répond sans authentification : quiconque l'atteint est root sur la machine"},
		"chk-es-open":       {"returns cluster information without authentication", "renvoie les informations du cluster sans authentification"},
		"chk-redis-open":    {"answered INFO without a password", "a répondu à INFO sans mot de passe"},
		"chk-auth-required": {"asks for a password before anything else", "exige un mot de passe avant toute chose"},

		"chk-http-redirect": {"redirects to HTTPS", "redirige vers HTTPS"},
		"chk-http-ip-404": {"answers 404 to the bare IP address: the reverse proxy only serves your domain names. Check the HTTPS redirect with your domain",
			"répond 404 à l'adresse IP seule : le reverse proxy ne sert que vos noms de domaine. Vérifiez la redirection HTTPS avec votre domaine"},
		"chk-http-plain":    {"serves pages without encryption", "sert des pages sans chiffrement"},
		"fix-http-redirect": {"Redirect every plain-HTTP request to HTTPS (301) and add Strict-Transport-Security.", "Redirigez toute requête HTTP vers HTTPS (301) et ajoutez Strict-Transport-Security."},

		"chk-tls-traefik-default": {"serves Traefik's default certificate: expected when reached by IP, but check that your domain gets its real certificate",
			"sert le certificat par défaut de Traefik : normal par adresse IP, mais vérifiez que votre domaine reçoit bien son vrai certificat"},
		"chk-tls-self-signed": {"uses a self-signed certificate: browsers show a warning", "utilise un certificat auto-signé : les navigateurs affichent une alerte"},
		"fix-tls-cert":        {"Use a certificate from a public CA (Let's Encrypt is free).", "Utilisez un certificat d'une autorité publique (Let's Encrypt est gratuit)."},
		"chk-tls-expiry":      {"its certificate expires in %d days", "son certificat expire dans %d jours"},
		"fix-tls-renew":       {"Renew the certificate, and automate renewals.", "Renouvelez le certificat, et automatisez les renouvellements."},
		"chk-tls-modern":      {"negotiates TLS 1.3 with a post-quantum key exchange", "négocie TLS 1.3 avec un échange de clés post-quantique"},
		"chk-tls-weak":        {"still accepts TLS 1.0 or 1.1", "accepte encore TLS 1.0 ou 1.1"},
		"fix-tls-weak":        {"Accept TLS 1.2 and 1.3 only.", "N'acceptez que TLS 1.2 et 1.3."},

		"chk-wings-auth": {"confirmed: Pterodactyl Wings, which requires a token for every request", "confirmé : Pterodactyl Wings, qui exige un jeton pour chaque requête"},
		"ev-wings":       {"its API answered with Wings' own error message", "son API a répondu avec le message d'erreur propre à Wings"},

		"prof-pterodactyl": {"a Pterodactyl game-hosting node", "un nœud d'hébergement de jeux Pterodactyl"},
		"prof-minecraft":   {"running Minecraft servers", "avec des serveurs Minecraft"},
		"prof-mail":        {"a mail server", "un serveur de mail"},
		"prof-web":         {"serving websites", "qui sert des sites web"},
		"prof-k3s":         {"under Kubernetes (k3s)", "sous Kubernetes (k3s)"},
		"prof-k8s":         {"under Kubernetes", "sous Kubernetes"},
		"prof-traefik":     {"behind the Traefik reverse proxy", "derrière le reverse proxy Traefik"},
		"prof-os":          {"on %s", "sur %s"},
		"prof-generic":     {"a machine exposing %d services", "une machine qui expose %d services"},
		"prof-generic-one": {"a machine exposing one service", "une machine qui expose un seul service"},

		"good-private-closed-one": {"the one sensitive port tested (a database, Docker, Kubernetes, an admin tool...) is not reachable",
			"le seul port sensible testé (base de données, Docker, Kubernetes, outil d'administration…) n'est pas joignable"},
		"good-private-closed": {"none of the %d sensitive ports tested (databases, Docker, Kubernetes, admin tools...) is reachable",
			"aucun des %d ports sensibles testés (bases de données, Docker, Kubernetes, outils d'administration…) n'est joignable"},
		"prof-machine": {"a machine", "une machine"},
		"colon":        {": ", " : "},

		"alert-blind": {"%s: all %d ports tested are filtered. Either the machine is off, or it (or a firewall on the way) is ignoring your address, for instance after spotting the scan. This scan cannot tell what the machine exposes: check again from another connection (a phone's hotspot, for instance).",
			"%s : les %d ports testés sont tous filtrés. Soit la machine est éteinte, soit elle (ou un pare-feu sur le chemin) ignore votre adresse, par exemple après avoir repéré le scan. Ce scan ne permet pas de savoir ce qu'elle expose : revérifiez depuis une autre connexion (le partage de connexion d'un téléphone, par exemple)."},
		// How the scan went (scanStory) and what the thorough analysis checked (diagnose).
		"story-whitelist": {"A firewall lets only the open ports through and drops everything else silently: the right setup.",
			"Un pare-feu ne laisse passer que les ports ouverts et jette tout le reste en silence : c'est la bonne configuration."},
		"story-no-firewall": {"The closed ports answer straight away with a reset (RST): no firewall filters them. A firewall that drops by default would tell a scanner less about the machine.",
			"Les ports fermés répondent directement par un RST : aucun pare-feu ne les filtre. Un pare-feu qui jette tout par défaut en dirait moins sur la machine."},
		"story-partial": {"A firewall drops most ports, but some get through to the machine with nothing listening behind them (closed: %s): maybe opening rules left behind.",
			"Un pare-feu jette la plupart des ports, mais certains passent jusqu'à la machine sans que rien n'y écoute (fermés : %s) : peut-être des règles d'ouverture oubliées."},
		"story-reject": {"A firewall refuses some ports out loud (%s): it answers with an ICMP error instead of keeping quiet.",
			"Un pare-feu refuse certains ports ouvertement (%s) : il répond par une erreur ICMP au lieu de se taire."},
		"story-slow": {"The open ports took up to %s ms to answer, close to the %s ms timeout: some \"filtered\" ports may only be slow. Scan again with -T2 for a longer timeout.",
			"Les ports ouverts ont mis jusqu'à %s ms à répondre, près du délai de %s ms : certains ports « filtrés » sont peut-être seulement lents. Relancez avec -T2 pour un délai plus long."},
		"diag-recheck":    {"checking that %s still answers…", "je vérifie que %s répond toujours…"},
		"diag-still-open": {"%s: the ports that were open still answer after the scan, so nothing blocked your address.", "%s : les ports ouverts répondent toujours après le scan, rien n'a bloqué votre adresse."},
		"diag-blocked-now": {"%s: ports %s answered during the scan and no longer do. The machine, or its protection (fail2ban, CrowdSec, an anti-DDoS...), blocked your address during the scan.",
			"%s : les ports %s répondaient pendant le scan et ne répondent plus. La machine, ou sa protection (fail2ban, CrowdSec, un anti-DDoS…), a bloqué votre adresse pendant le scan."},
		"diag-wait": {"waiting %d s to see whether the block lifts…", "j'attends %d s pour voir si le blocage se lève…"},
		"diag-unblocked": {"After %d s, port %d answers again: a temporary limit, triggered by the pace of the scan. Scan more slowly (--rate 50 -T2), or add your address to the protection's allow list.",
			"Après %d s, le port %d répond de nouveau : c'est une limitation temporaire, déclenchée par le rythme du scan. Scannez plus lentement (--rate 50 -T2), ou ajoutez votre adresse à la liste blanche de la protection."},
		"diag-still-blocked": {"Still blocked after %d s: a ban, not a slowdown. Unblock your address in the machine's protection (fail2ban, CrowdSec, anti-DDoS), and add it to its allow list before scanning again.",
			"Toujours bloqué après %d s : c'est un bannissement, pas un ralentissement. Débloquez votre adresse dans la protection de la machine (fail2ban, CrowdSec, anti-DDoS), et ajoutez-la à sa liste blanche avant de rescanner."},
		"diag-slow-probe": {"trying %s again, one slow connection at a time…", "je réessaie %s, une connexion lente à la fois…"},
		"diag-blind-answers": {"%s answers a single slow connection on port %d: it is the pace of the scan that got blocked, not your address for good. Scan more slowly (--rate 50 -T2), or add your address to the protection's allow list.",
			"%s répond à une connexion isolée sur le port %d : c'est le rythme du scan qui a été bloqué, pas votre adresse pour de bon. Scannez plus lentement (--rate 50 -T2), ou ajoutez votre adresse à la liste blanche de la protection."},
		"diag-blind-dead": {"%s: nothing answers, not even one slow connection, nor after a %d s pause. The machine is off, or your address is blocked entirely: check from another connection, and look at the machine's protection (fail2ban, CrowdSec, anti-DDoS).",
			"%s : rien ne répond, ni à une connexion isolée, ni après %d s de pause. La machine est éteinte, ou votre adresse est entièrement bloquée : vérifiez depuis une autre connexion, et regardez la protection de la machine (fail2ban, CrowdSec, anti-DDoS)."},
		"diag-banner-wait": {"waiting for the silent services of %s to speak…", "j'attends que les services muets de %s parlent…"},
		"diag-banner-late": {"Port %d: the service sent its banner after %s; service detection only waits half a second. The banner is now part of the analysis.",
			"Port %d : le service a envoyé sa bannière au bout de %s, alors que la détection de service n'attend qu'une demi-seconde. La bannière est maintenant prise en compte."},
		"diag-ssh-slow-hint": {"For SSH, the usual causes are UseDNS yes, a MaxStartups limit, or an anti-DDoS holding new connections back.",
			"Pour SSH, les causes habituelles sont UseDNS yes, une limite MaxStartups, ou un anti-DDoS qui retient les nouvelles connexions."},
		"diag-banner-none": {"Port %d: no banner even after %s, though %s speaks first: something holds the connection (an anti-DDoS, a SYN proxy), or it is not %s.",
			"Port %d : aucune bannière même après %s, alors que %s parle en premier : quelque chose retient la connexion (anti-DDoS, proxy SYN), ou ce n'est pas du %s."},

		"alert-mute": {"%s: its %d open ports accept connections, but no service answered on any of them. Something on the way (an anti-DDoS, a SYN proxy, a firewall) may be answering for the machine, or cutting the exchange short: what follows rests on the port numbers alone.",
			"%s : ses %d ports ouverts acceptent la connexion, mais aucun service n'a répondu. Un équipement sur le chemin (anti-DDoS, proxy SYN, pare-feu) répond peut-être à la place de la machine, ou coupe l'échange : ce qui suit repose sur les seuls numéros de port."},
		"alert-cluster-node": {"This scan runs from a Kubernetes node. The cluster's firewall may trust this machine and let it reach ports that are closed to the internet: check the cluster ports again from a machine outside the cluster before acting.",
			"Ce scan part d'un nœud Kubernetes. Le pare-feu du cluster fait peut-être confiance à cette machine et lui ouvre des ports fermés à Internet : revérifiez les ports du cluster depuis une machine extérieure au cluster avant d'agir."},
		"ev-cluster-node": {"seen from a Kubernetes node, which the cluster's firewall may trust", "vu depuis un nœud Kubernetes, auquel le pare-feu du cluster fait peut-être confiance"},
		"ev-silent":       {"the port accepts connections, but the service sent nothing back", "le port accepte la connexion, mais le service n'a rien répondu"},
		"ev-answered-late": {"the follow-up check got an answer in %s: the service is there, but answered too slowly for service detection",
			"la vérification approfondie a obtenu une réponse en %s : le service est bien là, mais il a répondu trop lentement pour la détection de service"},
		"chk-no-answer": {"could not be verified: nothing answered in %s (a firewall, a connection limit, or it is not %s)",
			"vérification impossible : rien n'a répondu en %s (pare-feu, limite de connexions, ou ce n'est pas du %s)"},

		"plan-many-ssh": {"%d SSH entry points face the internet: each is a door to defend. Keep the one you administer with, limit the others to known addresses",
			"%d accès SSH font face à Internet : chacun est une porte à défendre. Gardez celui qui sert à l'administration, limitez les autres à des adresses connues"},
	} {
		messages[k] = v
	}
}
